#include <iostream>
#include <string>
#include <vector>

struct Capacidad { int unidades; };
struct Existencias { int unidades; };
struct DepositoInvalido {};

class Deposito {
public:
    Deposito(Capacidad capacidad, Existencias existencias)
        : capacidad_{capacidad.unidades}, existencias_{existencias.unidades} {
        if (capacidad_ < 1 || capacidad_ > 20 || existencias_ < 0 || existencias_ > capacidad_) {
            throw DepositoInvalido{};
        }
    }
    int capacidad() const { return capacidad_; }
    int existencias() const { return existencias_; }
    int disponibles() const { return capacidad_ - existencias_; }
    bool agregar(int cantidad) {
        if (cantidad <= 0 || cantidad > capacidad_ - existencias_) { return false; }
        existencias_ += cantidad;
        return true;
    }
    bool retirar(int cantidad) {
        if (cantidad <= 0 || cantidad > existencias_) { return false; }
        existencias_ -= cantidad;
        return true;
    }
private:
    int capacidad_;
    int existencias_;
};

int main() {
    Deposito deposito{Capacidad{5}, Existencias{2}};
    std::cout << deposito.agregar(3) << ":" << deposito.existencias() << "\n";
    std::cout << deposito.agregar(1) << ":" << deposito.existencias() << "\n";
    std::cout << deposito.retirar(5) << ":" << deposito.existencias() << "\n";
    std::cout << deposito.retirar(1) << ":" << deposito.existencias();
    return 0;
}

